    pointer:`target.addEventListener('pointerdown', (event) => {\n  target.setPointerCapture(event.pointerId);\n  const rect = target.getBoundingClientRect();\n  grabOffset = event.clientY - rect.top;\n  pressed = true;\n});`,
    projection:`function project(velocity, rate = 0.998) {\n  return (velocity / 1000) * rate / (1 - rate);\n}\n\nconst projected = position + project(releaseVelocity);\nconst target = nearestSnapPoint(projected);`,
